using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using MyFundex.BuildingBlocks.Abstractions;using MyFundex.BuildingBlocks.Domain;using MyFundex.BuildingBlocks.Persistence;using MyFundex.Contracts;
namespace MyFundex.Audit;
public sealed class AuditEvent:EntityBase{public Guid AuditId{get;set;}public string Module{get;set;}="";public string EntityType{get;set;}="";public string EntityId{get;set;}="";public string Action{get;set;}="";public string? OldValue{get;set;}public string? NewValue{get;set;}public string? IpAddress{get;set;}public Guid CorrelationId{get;set;}public DateTimeOffset OccurredAt{get;set;}=DateTimeOffset.UtcNow;}
public sealed class AuditDbContext(DbContextOptions<AuditDbContext>o,ICurrentActor a):AuditableDbContext(o,a){public DbSet<AuditEvent>Events=>Set<AuditEvent>();protected override void OnModelCreating(ModelBuilder m) => ConfigureModel(m); public static void ConfigureModel(ModelBuilder m) {m.HasDefaultSchema("audit");ConfigureEntity(m.Entity<AuditEvent>());m.Entity<AuditEvent>().HasIndex(x=>x.AuditId).IsUnique();m.Entity<AuditEvent>().HasIndex(x=>new{x.Module,x.OccurredAt});}}
public sealed class AuditWriter(AuditDbContext db):IAuditWriter{public async Task WriteAsync(string module,string et,string eid,string action,string? oldv,string? newv,CancellationToken ct){db.Add(new AuditEvent{AuditId=MyFundex.BuildingBlocks.Ids.Uuid7.NewGuid(),Module=module,EntityType=et,EntityId=eid,Action=action,OldValue=oldv,NewValue=newv,CorrelationId=MyFundex.BuildingBlocks.Ids.Uuid7.NewGuid()});await db.SaveChangesAsync(ct);}}
public static class AuditModule{public static IServiceCollection AddAuditModule(this IServiceCollection s,string cs){s.AddDbContext<AuditDbContext>(o=>o.UseNpgsql(cs));s.AddScoped<IAuditWriter,AuditWriter>();return s;}}
